(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  const wy1 = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.016+t*0.35)*12;
  const wx2 = Math.sin((x+wx1)*0.025-t*0.5)*8 + Math.cos((y+wy1)*0.02+t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.025+t*0.45)*8 + Math.sin((x+wx1)*0.022-t*0.35)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 30+Math.cos(t*0.65+1)*50, 0.14, 2.1, 0.85],
    [420+Math.cos(t*0.55+2)*60, 210+Math.sin(t*0.75)*40, 0.11, 1.8, 1.05]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2 += Math.sin(d*f*1.6-t*sp*1.3+0.8)*w*0.5;
    iS2 += Math.cos(d*f*1.2+t*sp*0.9+2.1)*w*0.5;
  }
  const wSum = src.reduce((s,[,,,_,w])=>s+w,0);
  const act=(aS+aS2)/wSum, inh=(iS+iS2)/wSum;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*5+t*0.8)*0.15;
  const lattice=Math.sin(sx*0.08)*Math.sin(sy*0.08)*0.3
    +Math.sin((sx*0.707+sy*0.707)*0.06+t*0.3)*Math.sin((sx*0.707-sy*0.707)*0.06-t*0.3)*0.2;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+lattice)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*1.2)*Math.sin(sy*0.35-t*0.9)*0.08;
  const blend=reaction*0.65+cell*0.2+micro, v=blend*0.5+0.5;
  const pal=[
    [5,10,42],[10,35,85],[12,70,115],[18,115,130],
    [45,165,140],[130,195,110],[210,195,75],[225,145,60],
    [210,90,65],[175,50,80],[110,25,75],[50,15,55],[5,10,42]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120)|0)
  ];
}
